class Solution:
    def smallestNumber(self, n: int) -> int:
        return (1 << n.bit_length()) - 1

class Solution {
public:
    int smallestNumber(int n) {
        int x = 1;
        while (x - 1 < n) {
            x <<= 1;
        }
        return x - 1;
    }
};

class Solution {
    public int smallestNumber(int n) {
        int x = 1;
        while (x - 1 < n) {
            x <<= 1;
        }
        return x - 1;
    }
}

var smallestNumber = function(n) {
    let x = 1;
    while (x - 1 < n) {
        x <<= 1;
    }
    return x - 1;
};
